using System.Runtime.InteropServices;
using System.Runtime.Intrinsics;

namespace ProdOp;

public static class MathOps
{
    /// <summary>Computes the product of all elements using SIMD vectorization.</summary>
    public static float Product(ReadOnlySpan<float> values)
    {
        if (values.IsEmpty) return 0f;

        ref float start = ref MemoryMarshal.GetReference(values);
        int length = values.Length;
        int i = 0;

        // Use 256-bit vectors (8 floats) for the bulk of the work
        if (Vector256.IsHardwareAccelerated && length >= Vector256<float>.Count * 4)
        {
            var v0 = Vector256<float>.One;
            var v1 = Vector256<float>.One;
            var v2 = Vector256<float>.One;
            var v3 = Vector256<float>.One;
            int limit = length - (Vector256<float>.Count * 4 - 1);

            for (; i < limit; i += Vector256<float>.Count * 4)
            {
                v0 *= Vector256.LoadUnsafe(ref start, (nuint)i);
                v1 *= Vector256.LoadUnsafe(ref start, (nuint)(i + Vector256<float>.Count));
                v2 *= Vector256.LoadUnsafe(ref start, (nuint)(i + Vector256<float>.Count * 2));
                v3 *= Vector256.LoadUnsafe(ref start, (nuint)(i + Vector256<float>.Count * 3));
            }

            v0 = v0 * v1 * v2 * v3;

            // Handle remaining full vectors
            for (; i <= length - Vector256<float>.Count; i += Vector256<float>.Count)
                v0 *= Vector256.LoadUnsafe(ref start, (nuint)i);

            // Reduce vector to scalar
            var lo = v0.GetLower();
            var hi = v0.GetUpper();
            var combined = lo * hi;
            float product = combined[0] * combined[1] * combined[2] * combined[3];

            // Handle tail elements
            for (; i < length; i++)
                product *= Unsafe.Add(ref start, i);

            return product;
        }

        if (Vector128.IsHardwareAccelerated && length >= Vector128<float>.Count * 4)
        {
            var v0 = Vector128<float>.One;
            var v1 = Vector128<float>.One;
            var v2 = Vector128<float>.One;
            var v3 = Vector128<float>.One;
            int limit = length - (Vector128<float>.Count * 4 - 1);

            for (; i < limit; i += Vector128<float>.Count * 4)
            {
                v0 *= Vector128.LoadUnsafe(ref start, (nuint)i);
                v1 *= Vector128.LoadUnsafe(ref start, (nuint)(i + Vector128<float>.Count));
                v2 *= Vector128.LoadUnsafe(ref start, (nuint)(i + Vector128<float>.Count * 2));
                v3 *= Vector128.LoadUnsafe(ref start, (nuint)(i + Vector128<float>.Count * 3));
            }

            v0 = v0 * v1 * v2 * v3;

            for (; i <= length - Vector128<float>.Count; i += Vector128<float>.Count)
                v0 *= Vector128.LoadUnsafe(ref start, (nuint)i);

            float product = v0[0] * v0[1] * v0[2] * v0[3];

            for (; i < length; i++)
                product *= Unsafe.Add(ref start, i);

            return product;
        }

        // Scalar fallback with 4x unrolling to hide multiply latency
        float p0 = 1f, p1 = 1f, p2 = 1f, p3 = 1f;
        int scalarLimit = length - 3;
        for (; i < scalarLimit; i += 4)
        {
            p0 *= Unsafe.Add(ref start, i);
            p1 *= Unsafe.Add(ref start, i + 1);
            p2 *= Unsafe.Add(ref start, i + 2);
            p3 *= Unsafe.Add(ref start, i + 3);
        }
        for (; i < length; i++)
            p0 *= Unsafe.Add(ref start, i);

        return p0 * p1 * p2 * p3;
    }
}

